<?php
$root=dirname(__DIR__);$s=file_get_contents($root.'/routes/web.php');preg_match_all("/\\[([A-Za-z_][A-Za-z0-9_]*Controller)::class\\s*,\\s*'([^']+)'\\]/",$s,$m,PREG_SET_ORDER);$bad=[];$checked=0;foreach($m as $x){[$all,$c,$method]=$x;$paths=[$root."/app/Http/Controllers/$c.php",$root."/app/Http/Controllers/Admin/$c.php"];$file=null;foreach($paths as $p)if(is_file($p)){$file=$p;break;}if(!$file){$bad[]="MISSING CLASS FILE: $c::$method";continue;}$body=file_get_contents($file);$checked++;if(!preg_match('/function\\s+'.preg_quote($method,'/').'\\s*\\(/',$body))$bad[]="MISSING METHOD: $c::$method";}echo "Checked route actions: $checked\\n";if($bad){echo implode("\\n",array_unique($bad))."\\n";exit(1);}echo "OK: all routed controller files and methods exist.\\n";